"""
generator/code_generator.py
Takes ProgramAnalysis and original source code, produces a complete
polyglot package: native source files + modified orchestrator.
"""
import os, re, textwrap
from pathlib import Path
from analyzer.ai_analyzer import ProgramAnalysis, FunctionAnalysis, SUPPORTED_LANGUAGES, TARGET_LANGUAGES

# ── Polyglot injection templates per orchestrator language ────────────────────

PYTHON_POLYGLOT_HEADER = '''# ── GraalVM Polyglot Runtime ─────────────────────────────────────────────────
# Auto-generated by GraalVM Optimizer
# Original program preserved as orchestrator; hot functions run natively.
import sys, os
_POLYGLOT_DIR = os.path.join(os.path.dirname(os.path.abspath(__file__)), "native")

try:
    import polyglot as _polyglot
    _GRAAL = True
except ImportError:
    _GRAAL = False
    import ctypes as _ctypes

def _load_native(name, lang="llvm"):
    """Load a native module — GraalVM polyglot or ctypes fallback."""
    if _GRAAL:
        bc = open(os.path.join(_POLYGLOT_DIR, name + ".bc"), "rb").read()
        return _polyglot.eval(language=lang, string=bc)
    else:
        # ctypes fallback for non-GraalVM environments
        so = os.path.join(_POLYGLOT_DIR, name + ".so")
        return _ctypes.CDLL(so)

def _load_js(name):
    if _GRAAL:
        src = open(os.path.join(_POLYGLOT_DIR, name + ".js")).read()
        return _polyglot.eval(language="js", string=src)
    else:
        raise RuntimeError("JavaScript polyglot requires GraalVM. Install from https://www.graalvm.org")

# ─────────────────────────────────────────────────────────────────────────────
'''

JAVA_POLYGLOT_HEADER = '''// Auto-generated by GraalVM Optimizer - polyglot runtime bridge
import org.graalvm.polyglot.*;
import java.io.File;
import java.util.HashMap;
import java.util.HashSet;

class _GraalContext {
    private static Context ctx;
    private static final HashMap<String, Value> modules = new HashMap<>();
    private static final HashSet<String> failed = new HashSet<>();
    static final String NATIVE_DIR;
    // Set -Dnative.disabled=true to force Java fallback path (used by BenchmarkSuite)
    static final boolean NATIVE_DISABLED =
        "true".equalsIgnoreCase(System.getProperty("native.disabled", "false"));

    static {
        String nd = System.getProperty("native.dir");
        if (nd == null) nd = System.getProperty("user.dir") + "/native";
        NATIVE_DIR = nd;
        if (!NATIVE_DISABLED) {
            try {
                ctx = Context.newBuilder()
                    .allowAllAccess(true)
                    .option("engine.WarnInterpreterOnly", "false")
                    .build();
            } catch (Exception e) {
                ctx = null;
                System.err.println("[GraalVM] Could not create context: " + e.getMessage());
            }
        }
    }

    static boolean isAvailable() { return ctx != null && !NATIVE_DISABLED; }

    static Value loadLLVM(String name) {
        if (NATIVE_DISABLED) return null;
        if (modules.containsKey(name)) return modules.get(name);
        if (failed.contains(name) || ctx == null) return null;
        try {
            File bc = new File(NATIVE_DIR + "/" + name + ".bc");
            Source src = Source.newBuilder("llvm", bc).build();
            ctx.eval(src);
            Value bindings = ctx.getBindings("llvm");
            modules.put(name, bindings);
            return bindings;
        } catch (Exception e) {
            System.err.println("[GraalVM] Failed to load " + name + ".bc: " + e.getMessage());
            failed.add(name);
            return null;
        }
    }

    static Value fn(String module, String funcName) {
        Value mod = loadLLVM(module);
        if (mod == null) return null;
        return mod.getMember(funcName);
    }
}
// ---------------------------------------------------------------------------
'''

